CREATE ROLE atlas_logical_reader;
CREATE TABLE atlas_logical_secure(tenant name NOT NULL, payload text NOT NULL);
ALTER TABLE atlas_logical_secure ENABLE ROW LEVEL SECURITY;
CREATE POLICY atlas_security_policy ON atlas_logical_secure USING (tenant = current_user);
GRANT SELECT ON atlas_logical_secure TO atlas_logical_reader;
INSERT INTO atlas_logical_secure VALUES ('atlas_logical_reader', 'visible'), ('postgres', 'hidden');
CREATE ROLE atlas_logical_reader;
CREATE TABLE atlas_logical_secure(tenant name NOT NULL, payload text NOT NULL);
ALTER TABLE atlas_logical_secure ENABLE ROW LEVEL SECURITY;
CREATE POLICY atlas_security_policy ON atlas_logical_secure USING (tenant = current_user);
GRANT SELECT ON atlas_logical_secure TO atlas_logical_reader;
SET ROLE atlas_logical_reader;
SELECT CASE WHEN count(*) = 1 AND min(payload) = 'visible'
  THEN 'ATLAS_SECURITY_PASS:operations.logical-replication'
  ELSE 'ATLAS_SECURITY_FAIL:operations.logical-replication' END
FROM atlas_logical_secure;
DO $$ BEGIN
  UPDATE atlas_logical_secure SET payload = 'forged';
  RAISE EXCEPTION 'update unexpectedly allowed';
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'ATLAS_SECURITY_PASS:operations.logical-replication';
END $$;
RESET ROLE;

